# R52: the app-wide layers and route states (coverage.md wave 4), drawn over Learn: the search palette (Recent
# searches, Suggestions, results by group, Nothing found), the MIDI button's popover in each state, the Shortcuts
# sheet, the Welcome dialog, the update banner, Storage full, the account-deletion gate, and the route states
# (Loading, Something went wrong, offline, Page not found). Strings from inventory.md's GLOBAL. Exec'd last.

MIDII = '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 2v6M15 2v6M6 8h12v4a6 6 0 0 1-12 0zM12 18v4"></path></svg>'
KBDI = '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="2" y="6" width="20" height="12" rx="2"></rect><path d="M6 10h.01M10 10h.01M14 10h.01M18 10h.01M7 14h10"></path></svg>'
SRCH = [('Practice', [('C major', 'Scale', 'Scales.dc.html'), ('Cmaj7', 'Chord', 'Chords.dc.html'), ('ii–V–I in C', 'Progression', 'Progression.dc.html')]),
        ('Songs', [('Amazing Grace', 'John Newton · C major', 'Song.dc.html'), ('Canon in D', 'Pachelbel · D major', 'Song.dc.html'), ('Clair de lune', 'Debussy · D♭ major · Archived', 'Song.dc.html')]),
        ('Folders', [('Church', '12 songs', 'Songs.dc.html'), ('Classical', '8 songs', 'Songs.dc.html')]),
        ('Lessons', [('How major scales work', 'Beginner · Chapter 3', 'Lesson.dc.html'), ('Chords in a major key', 'Beginner · Chapter 4', 'Lesson.dc.html')])]
G_JS = js('const SRCH = ' + json.dumps(SRCH, ensure_ascii=False) + r''';
    const S = (o) => set(o), q = (st.q ?? '').trim().toLowerCase(), layer = st.layer ?? null, midi = st.midi ?? 'idle';
    const groups = SRCH.map(([g, rs]) => ({ g, rs: rs.filter(([t, s]) => !q || (t + ' ' + s).toLowerCase().includes(q)).map(([t, s, h]) => ({ t, s, h, arch: s.includes('Archived'), sub: s.replace(' · Archived', '') })) })).filter((g) => g.rs.length);
    const L = ['Welcome', 'Update', 'Storage full', 'Deletion', 'Loading', 'Error', 'Offline', 'Not found'];
    const MS = { idle: ['Connect a MIDI keyboard', 'Plug a keyboard in by USB, or pair it by Bluetooth.', 'Connect', '#9A9089'], busy: ['Connecting…', 'Allow MIDI when the browser asks.', '', '#C9A227'], none: ['No MIDI keyboard found.', 'Check the cable or the pairing, then try again.', 'Try again', '#B3261E'], on: ['Connected: Roland FP-30X', 'Play a key: the notes light on the screen.', 'MIDI devices', '#44684A'] };
    const m = MS[midi];
    const lang = st.lang ?? 'English';
    return { ...common(st, set), q: st.q ?? '', setQ: (e) => S({ q: e.target.value }), clearQ: () => S({ q: '' }), typing: !!q, notTyping: !q, groups, found: groups.length > 0, nothing: !!q && !groups.length,
      openSearch: () => S({ sheet: 'search' }), searchOn: st.sheet === 'search', recent: (k) => () => S({ q: k }), r0: () => S({ q: 'canon' }), r1: () => S({ q: 'cmaj7' }), r2: () => S({ q: 'scales' }),
      openMidi: () => S({ sheet: 'midi' }), midiOn: st.sheet === 'midi', midiT: m[0], midiS: m[1], midiB: m[2], midiDot: m[3], midiHasB: !!m[2], midiBusy: midi === 'busy', midiL: midi === 'on' ? 'MIDI keyboard, connected' : 'MIDI keyboard', midiLit: midi === 'on' ? '#44684A' : 'transparent',
      midiGo: () => { if (midi === 'on') return; if (midi === 'none' || midi === 'idle') { S({ midi: 'busy' }); setTimeout(() => S({ midi: (st.tries ?? 0) % 2 ? 'on' : 'none', tries: (st.tries ?? 0) + 1 }), 1100); } },
      openKeys: () => S({ sheet: 'keys' }), keysOn: st.sheet === 'keys', closeSheet: () => S({ sheet: null }),
      layers: L.map((l) => ({ l, bg: layer === l ? '#332921' : '#EEE9E2', fg: layer === l ? '#FEFDFB' : '#332921', pick: () => S({ layer: layer === l ? null : l, upd: null }) })),
      welcomeOn: layer === 'Welcome', updateOn: layer === 'Update', storeOn: layer === 'Storage full', delOn: layer === 'Deletion', loadOn: layer === 'Loading', errOn: layer === 'Error', offOn: layer === 'Offline', nfOn: layer === 'Not found',
      isRoute: ['Loading', 'Error', 'Offline', 'Not found'].includes(layer), notRoute: !['Loading', 'Error', 'Offline', 'Not found'].includes(layer),
      closeLayer: () => S({ layer: null }), updT: st.upd ? 'Restarting…' : 'A new version is ready', updNow: () => { S({ upd: true }); setTimeout(() => S({ layer: null, upd: null }), 1200); }, updIdle: !st.upd,
      langs: ['English', 'Русский'].map((l) => ({ l, on: l === lang, bg: l === lang ? '#FEFDFB' : 'transparent', sh: l === lang ? '0 1px 2px rgba(51,41,33,.18), 0 0 0 0.5px rgba(51,41,33,.08)' : 'none', fw: l === lang ? 600 : 500, pick: () => S({ lang: l }) })) };''')

# the page under the layers: Learn, quiet
MIDIB = f'<button type="button" aria-label="{{{{midiL}}}}" onClick="{{{{openMidi}}}}" style="position: relative; width: 44px; height: 44px; border: 0; background: transparent; color: {INK}; display: flex; align-items: center; justify-content: center">{MIDII}<span style="position: absolute; right: 9px; bottom: 9px; width: 9px; height: 9px; border-radius: 5px; background: {{{{midiLit}}}}"></span></button>'
GBAR = IB('Search', SEARCH.replace('18', '22'), 'openSearch') + MIDIB + IB('Shortcuts', KBDI, 'openKeys')
UNDER = (CARD(f'<span style="font-size: 13px; font-weight: 600; color: #A8551F">Continue</span><span style="display: block; font-family: {SERIF}; font-size: 22px; margin-top: 4px">How major scales work</span><span style="font-size: 13px; color: {SOFT}">Beginner · 7 of 18 learned</span>')
         + H2('Chapter 3: Scales and keys') + BOXG(*[f'<div style="min-height: 56px; display: flex; align-items: center; gap: 12px; padding: 8px 16px"><span style="width: 28px; height: 28px; border-radius: 8px; background: {c}"></span><span style="font-size: 16px">{t}</span></div>' for t, c in [('Tones and semitones', SAGE), ('How major scales work', HONEY), ('Keys with sharps', FILL), ('Keys with flats', FILL)]]))
# the search palette
SROW9 = (f'<a href="{{{{r.h}}}}" style="min-height: 52px; display: flex; align-items: center; gap: 12px; padding: 6px 16px; color: {INK}; text-decoration: none; box-shadow: inset 0 -1px 0 {FILL}"><span style="flex: 1; display: flex; flex-direction: column; gap: 1px"><span style="font-size: 16px; font-weight: 600">{{{{r.t}}}}</span><span style="font-size: 13px; color: {SOFT}">{{{{r.sub}}}}</span></span>'
         f'<sc-if value="{{{{r.arch}}}}" hint-placeholder-val="{{{{false}}}}"><span style="height: 24px; padding: 0 8px; border-radius: 12px; background: {FILL}; font-size: 12px; font-weight: 600; color: {SOFT}; display: flex; align-items: center">Archived</span></sc-if></a>')
CHIPQ = lambda t, act: f'<button type="button" onClick="{{{{{act}}}}}" style="height: 44px; padding: 0 14px; border: 0; border-radius: 22px; background: {FILL}; color: {INK}; font: inherit; font-size: 15px">{t}</button>'
PAL = (f'<label style="height: 48px; border-radius: 12px; background: {SHEET}; box-shadow: 0 0 0 1px {LINE}; display: flex; align-items: center; gap: 8px; padding: 0 4px 0 12px; color: {SOFT}">{SEARCH}<input value="{{{{q}}}}" onInput="{{{{setQ}}}}" placeholder="Songs, chords, scales, lessons…" aria-label="Search everything" style="flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font: inherit; font-size: 16px; color: {INK}">'
       f'<sc-if value="{{{{typing}}}}" hint-placeholder-val="{{{{false}}}}"><button type="button" aria-label="Clear search" onClick="{{{{clearQ}}}}" style="width: 44px; height: 44px; border: 0; background: transparent; color: {SOFT}; display: flex; align-items: center; justify-content: center">{CLOSE.replace("24", "18")}</button></sc-if></label>'
       f'<sc-if value="{{{{notTyping}}}}" hint-placeholder-val="{{{{true}}}}">{CAPS("Recent searches")}<div style="display: flex; flex-wrap: wrap; gap: 8px">{CHIPQ("canon", "r0")}{CHIPQ("Cmaj7", "r1")}{CHIPQ("scales", "r2")}</div>{CAPS("Suggestions")}'
       + GROUP(('link', 'Continue: How major scales work', '', 'Lesson.dc.html'), ('link', 'Chords', '', 'Chords.dc.html'), ('link', 'Metronome', '', 'Metronome.dc.html'), bg=SHEET) + '</sc-if>'
       f'<sc-if value="{{{{found}}}}" hint-placeholder-val="{{{{false}}}}"><sc-if value="{{{{typing}}}}" hint-placeholder-val="{{{{false}}}}"><sc-for list="{{{{groups}}}}" as="g" hint-placeholder-count="3"><section style="display: flex; flex-direction: column; gap: 6px">{CAPS("{{g.g}}")}<div style="border-radius: 14px; background: {SHEET}; box-shadow: 0 0 0 1px {LINE}; overflow: hidden"><sc-for list="{{{{g.rs}}}}" as="r" hint-placeholder-count="2">{SROW9}</sc-for></div></section></sc-for></sc-if></sc-if>'
       f'<sc-if value="{{{{nothing}}}}" hint-placeholder-val="{{{{false}}}}"><div style="display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 40px 16px; text-align: center"><span style="font-size: 18px; font-weight: 700">Nothing found.</span><span style="font-size: 15px; color: {SOFT}">Try a song’s title, a chord like Cmaj7, or a key.</span>{CHIPQ("Clear search", "clearQ")}</div></sc-if>')
# MIDI popover
MIDIBODY = (f'<div style="display: flex; align-items: center; gap: 10px"><span style="width: 10px; height: 10px; border-radius: 5px; background: {{{{midiDot}}}}"></span><span style="font-size: 16px; font-weight: 600">{{{{midiT}}}}</span></div><span style="font-size: 15px; line-height: 1.45; color: {SOFT}">{{{{midiS}}}}</span>'
            f'<sc-if value="{{{{midiHasB}}}}" hint-placeholder-val="{{{{true}}}}"><div style="display: flex">{BTN("{{midiB}}", "midiGo", "", "primary", 48)}</div></sc-if>')
KEYSB = ''.join(SEC(CAPS(g), BOXG(*[f'<div style="min-height: 48px; display: flex; align-items: center; gap: 12px; padding: 6px 16px"><span style="flex: 1; font-size: 16px">{a}</span><span style="display: flex; gap: 4px">' + ''.join(f'<kbd style="min-width: 28px; height: 28px; padding: 0 8px; box-sizing: border-box; border-radius: 6px; background: {FILL}; box-shadow: inset 0 -1px 0 {LINE}; font: inherit; font-size: 13px; font-weight: 600; display: flex; align-items: center; justify-content: center">{k}</kbd>' for k in ks) + '</span></div>' for a, ks in rows]))
                for g, rows in [('This screen', [('Search everything', ['Ctrl', 'K']), ('Edit', ['E'])]), ('Anywhere', [('Collapse or open the sidebar', ['Ctrl', '\\']), ('Show the shortcuts', ['?'])]), ('Piano keys', [('Play the keys', ['A', '…', 'K']), ('An octave down, up', ['Z', 'X']), ('Hold the pedal', ['Space'])])])
# layers
DLGBOX = lambda inner, w=372: f'<div onClick="{{{{closeLayer}}}}" style="position: absolute; inset: 0; z-index: 70; background: rgba(51,41,33,.32)"></div><div role="dialog" style="position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); z-index: 71; width: {w}px; max-width: calc(100% - 40px); box-sizing: border-box; border-radius: 22px; background: {PAGE}; padding: 24px 20px 20px; box-shadow: 0 0 0 1px {LINE}, {SHADOW}; display: flex; flex-direction: column; gap: 12px">{inner}</div>'
WELCOME = (f'<sc-if value="{{{{welcomeOn}}}}" hint-placeholder-val="{{{{false}}}}">' + DLGBOX(f'<span style="align-self: center; width: 72px; height: 72px; border-radius: 18px; background: {INK}; color: {ACCENT}; display: flex; align-items: center; justify-content: center; font-family: {SERIF}; font-size: 40px">𝄞</span>'
           f'<span style="text-align: center; font-size: 24px; font-weight: 700">Welcome to Piano Trainer</span><span style="text-align: center; font-size: 16px; line-height: 1.45; color: {SOFT}">Learn songs, chords and scales at the piano, at your own pace.</span>'
           f'{CAPS("Language")}<div style="display: grid">{SEGC("langs", 44, 15)}</div><div style="display: grid; gap: 8px; margin-top: 6px">{BTN("Start playing", "closeLayer", "", "primary", 50)}{BTN("Sign in", "", "SignIn.dc.html", "quiet", 50)}</div>', 400) + '</sc-if>')
DELGATE = f'<sc-if value="{{{{delOn}}}}" hint-placeholder-val="{{{{false}}}}">' + DLGBOX(f'<span style="font-size: 20px; font-weight: 700">Account scheduled for deletion</span><span style="font-size: 15px; line-height: 1.45; color: {SOFT}">It will be deleted on 11 December 2026. Keep it, or sign out and let the deletion proceed.</span><div style="display: flex; gap: 8px; margin-top: 6px">{BTN("Sign out", "closeLayer", "", "quiet", 44)}{BTN("Keep account", "closeLayer", "", "primary", 44)}</div>') + '</sc-if>'
BANNER = lambda pos: (f'<sc-if value="{{{{updateOn}}}}" hint-placeholder-val="{{{{false}}}}"><div role="status" style="position: absolute; {pos}; z-index: 56; min-height: 56px; border-radius: 16px; background: {INK}; color: {SHEET}; display: flex; align-items: center; gap: 8px; padding: 6px 6px 6px 16px; font-size: 15px; box-shadow: {SHADOW}"><span style="flex: 1; font-weight: 600">{{{{updT}}}}</span>'
                      f'<sc-if value="{{{{updIdle}}}}" hint-placeholder-val="{{{{true}}}}"><button type="button" onClick="{{{{closeLayer}}}}" style="height: 44px; padding: 0 12px; border: 0; background: transparent; color: {SHEET}; font: inherit; font-size: 15px">Later</button><button type="button" onClick="{{{{updNow}}}}" style="height: 44px; padding: 0 16px; border: 0; border-radius: 22px; background: {ACCENT}; color: {INK}; font: inherit; font-size: 15px; font-weight: 700">Update</button></sc-if></div></sc-if>'
                      f'<sc-if value="{{{{storeOn}}}}" hint-placeholder-val="{{{{false}}}}"><div role="alert" style="position: absolute; {pos}; z-index: 56; border-radius: 16px; background: #F6DEDA; color: #5C1410; display: flex; flex-direction: column; gap: 6px; padding: 14px 14px 10px 16px; box-shadow: {SHADOW}"><span style="font-size: 16px; font-weight: 700">This device is out of room: your last change was not saved.</span>'
                      f'<span style="font-size: 14px; line-height: 1.4">Download a backup in Settings, then delete takes you no longer need.</span><div style="display: flex; justify-content: flex-end; gap: 4px"><button type="button" aria-label="Close the notice" onClick="{{{{closeLayer}}}}" style="height: 44px; padding: 0 12px; border: 0; background: transparent; color: #5C1410; font: inherit; font-size: 15px">Close</button><a href="Settings.dc.html" style="height: 44px; padding: 0 16px; border-radius: 22px; background: #5C1410; color: #FFFFFF; font-size: 15px; font-weight: 700; text-decoration: none; display: flex; align-items: center">Settings</a></div></div></sc-if>')
ROUTE = (f'<sc-if value="{{{{loadOn}}}}" hint-placeholder-val="{{{{false}}}}"><div role="status" aria-label="Loading" style="flex: 1; display: flex; flex-direction: column; gap: 12px; padding: 8px 16px">' + ''.join(f'<span style="height: {h}px; border-radius: 14px; background: {FILL}; opacity: {o}"></span>' for h, o in [(36, .9), (96, .8), (24, .7), (56, .6), (56, .5), (56, .4)]) + '</div></sc-if>'
         + ''.join(f'<sc-if value="{{{{{c}}}}}" hint-placeholder-val="{{{{false}}}}"><div style="flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; padding: 24px; text-align: center"><span style="width: 72px; height: 72px; border-radius: 36px; background: {bg}; color: {INK}; font-size: 30px; font-weight: 700; display: flex; align-items: center; justify-content: center">{ic}</span>'
                   f'<span style="font-size: 22px; font-weight: 700">{t}</span><span style="font-size: 16px; line-height: 1.45; color: {SOFT}; max-width: 340px">{b}</span><div style="display: flex; gap: 8px; margin-top: 8px">{btns}</div></div></sc-if>'
                   for c, ic, bg, t, b, btns in [('errOn', '!', '#F6DEDA', 'Something went wrong', 'The screen could not open. Reloading usually fixes it; the error has been sent so it can be fixed.', BTN('Back', 'closeLayer', '', 'quiet', 48, False) + BTN('Reload', 'closeLayer', '', 'primary', 48, False)),
                                                 ('offOn', '⌁', HONEY, 'Something went wrong', 'You’re offline. This screen opens once you’re back online.', BTN('Back', 'closeLayer', '', 'quiet', 48, False) + BTN('Reload', 'closeLayer', '', 'primary', 48, False)),
                                                 ('nfOn', '?', FILL, 'Page not found', 'The link may be old, or the song or lesson was deleted.', BTN('Go to Learn', 'closeLayer', '', 'primary', 48, False))]))
DEMOSTRIP = lambda: (f'<div aria-label="Canvas: show a layer" style="flex: none; margin: 0 12px 8px; padding: 6px; border-radius: 14px; border: 1.5px dashed {LINE}; display: flex; flex-wrap: wrap; gap: 6px; align-items: center"><span style="font-size: 12px; font-weight: 700; color: {SOFT}; padding: 0 4px">CANVAS · SHOW</span>'
                     f'<sc-for list="{{{{layers}}}}" as="p" hint-placeholder-count="8"><button type="button" onClick="{{{{p.pick}}}}" style="height: 32px; padding: 0 10px; border: 0; border-radius: 16px; background: {{{{p.bg}}}}; color: {{{{p.fg}}}}; font: inherit; font-size: 13px; font-weight: 600">{{{{p.l}}}}</button></sc-for></div>')
gph = (f'{TOP("", "", GBAR)}<sc-if value="{{{{notRoute}}}}" hint-placeholder-val="{{{{true}}}}">{LARGE("Learn")}<main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; padding: 0 16px 24px; display: flex; flex-direction: column; gap: 16px">{UNDER}</main></sc-if>{ROUTE}{DEMOSTRIP()}<div style="height: 96px; flex: none"></div>{TABBAR("Learn")}'
       + WELCOME + DELGATE + BANNER('left: 12px; right: 12px; top: 58px'))
glm = (f'{LTOP("", GBAR)}<sc-if value="{{{{notRoute}}}}" hint-placeholder-val="{{{{true}}}}"><main class="nos" style="flex: 1; min-height: 0; overflow-y: auto; padding: 0 56px 24px; display: flex; justify-content: center"><div style="width: 760px; display: flex; flex-direction: column; gap: 16px"><h1 style="margin: 0; font-size: 34px; font-weight: 700">Learn</h1>{UNDER}</div></main></sc-if>{ROUTE}{DEMOSTRIP()}'
       + WELCOME.replace('SignIn.dc.html', 'SignInLaptop.dc.html') + DELGATE + BANNER('right: 28px; bottom: 28px; width: 440px').replace('Settings.dc.html', 'SettingsLaptop.dc.html'))
GSHEETS = BSHEET('searchOn', 'Search', PAL) + BSHEET('midiOn', 'MIDI keyboard', MIDIBODY) + BSHEET('keysOn', 'Shortcuts', KEYSB)
GPOPS = (f'<sc-if value="{{{{searchOn}}}}" hint-placeholder-val="{{{{false}}}}"><div onClick="{{{{closeSheet}}}}" style="position: absolute; inset: 0; z-index: 60; background: rgba(51,41,33,.24)"></div><div role="dialog" aria-label="Search" class="nos" style="position: absolute; left: 50%; top: 96px; transform: translateX(-50%); z-index: 61; width: 640px; max-height: 680px; overflow-y: auto; box-sizing: border-box; border-radius: 20px; background: {PAGE}; padding: 16px; box-shadow: 0 0 0 1px {LINE}, {SHADOW}; display: flex; flex-direction: column; gap: 12px">'
         + PAL.replace('Lesson.dc.html', 'LessonLaptop.dc.html').replace('Chords.dc.html', 'ChordsLaptop.dc.html').replace('Metronome.dc.html', 'MetronomeLaptop.dc.html') + f'<span style="font-size: 13px; color: {SOFT}">Up and down move through the results, Enter opens one, Escape closes.</span></div></sc-if>'
         + POPOVER('midiOn', 'MIDI keyboard', MIDIBODY, 'right: 80px; top: 64px', 340) + POPOVER('keysOn', 'Shortcuts', KEYSB, 'right: 40px; top: 64px', 440))
detail('AppLayers', 'Across the app', G_JS, gph, glm, '', GSHEETS, GPOPS, 'Learn')
print('r52 global ok')
